{
  "managed-by": "managed-by: personal-multi-harness-workstation-configuration; source: overlay/model-defaults.json; release: unknown, not a git checkout (.bumpversion.toml says 10.1.0); commit: unknown; do not edit, re-run the installer",
  "note": "The session-start model and effort keys this project set, per file, and under \"replaced\" the value each one replaced; uninstall restores those and removes the rest.",
  "set": {
    "<T>/home/.claude/settings.json": {
      "harness": "claude-code",
      "keys": {
        "model": "claude-opus-5-5[1m]",
        "effortLevel": "medium"
      },
      "replaced": {
        "model": "owner-model"
      }
    },
    "<T>/home/.codex/config.toml": {
      "harness": "codex",
      "keys": {
        "model": "gpt-5.6-sol",
        "model_reasoning_effort": "medium"
      },
      "replaced": {
        "model_reasoning_effort": "high"
      }
    },
    "<T>/home/.kiro/settings/cli.json": {
      "harness": "kiro-cli",
      "keys": {
        "chat.defaultModel": "claude-sonnet-4.5"
      }
    }
  }
}

